    if(today&&((to-from).TotalHours<23||(to-from).TotalHours>25))return false;
    var buckets=UsageObjects(WidgetClient.Get(range,"buckets"),today?13:14);if(buckets==null||buckets.Count==0)return false;
    long input=0,output=0,total=0,responses=0,increments=0;DateTimeOffset prior=from;
