    static bool ValidObservedTriple(object raw,string updatedAt,out UsageTriple triple){
     triple=null;var usage=WidgetClient.Obj(raw);long input,output,total;
     if(updatedAt==null||!TimestampValid(updatedAt)||!UsageTripleValid(usage,out input,out output,out total))return false;
     triple=new UsageTriple{Input=input,Output=output,Total=total,UpdatedAt=updatedAt};return true;
    }
    bool SnapshotTripleValid(SelectedSnapshot snapshot){
     return snapshot!=null&&snapshot.Triple!=null&&snapshot.Triple.Input>=0&&snapshot.Triple.Output>=0&&snapshot.Triple.Total>=0&&snapshot.Triple.Total==snapshot.Triple.Input+snapshot.Triple.Output&&TimestampValid(snapshot.Triple.UpdatedAt);
    }
    static int SourceRank(string source){
     return source=="selected"?3:source=="root_turn"?2:source=="legacy_session"?1:0;
    }
    static bool NewerOrEqual(string candidate,string prior){
     if(String.IsNullOrEmpty(candidate))return false;
     if(String.IsNullOrEmpty(prior))return true;
     DateTimeOffset next,current;
     if(!TimestampValid(candidate)||!TimestampValid(prior))return false;
     next=DateTimeOffset.Parse(candidate,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind);
     current=DateTimeOffset.Parse(prior,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind);
     return next>=current;
    }
    static int CompareObserved(string candidate,string prior){
     if(String.IsNullOrEmpty(candidate))return -1;
     if(String.IsNullOrEmpty(prior))return 1;
     if(!TimestampValid(candidate)||!TimestampValid(prior))return -1;
     var next=DateTimeOffset.Parse(candidate,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind);
     var current=DateTimeOffset.Parse(prior,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind);
     return next.CompareTo(current);
    }
    bool StoreTriple(SelectedSnapshot snapshot,string source,object raw,string updatedAt){
     UsageTriple triple;if(snapshot==null||!ValidObservedTriple(raw,updatedAt,out triple))return false;
     string prior=source=="selected"?snapshot.UsageWatermark:source=="root_turn"?snapshot.RootUsageWatermark:snapshot.LegacySeenAt;
     if(!NewerOrEqual(updatedAt,prior))return false;
     if(source=="selected")snapshot.UsageWatermark=updatedAt;
     else if(source=="root_turn")snapshot.RootUsageWatermark=updatedAt;
     else snapshot.LegacySeenAt=updatedAt;
     if(source!="selected"&&snapshot.SelectedCandidate)return false;
     int time=CompareObserved(updatedAt,snapshot.TripleUpdatedAt);
     if(source!="selected"&&(time<0||time==0&&SourceRank(source)<SourceRank(snapshot.TripleSource)))return false;
     snapshot.Triple=triple;snapshot.TripleSource=source;snapshot.TripleUpdatedAt=updatedAt;
     return true;
    }
    void StoreTriple(SelectedSnapshot snapshot,string source,Dictionary<string,object> block){
     if(block==null)return;
     StoreTriple(snapshot,source,WidgetClient.Get(block,"usage"),WidgetClient.Str(block,"updatedAt"));
    }
