     if(task==null||!String.Equals(WidgetClient.Str(task,"id"),taskId,StringComparison.Ordinal))return null;
     Dictionary<string,object> root=null;int matches=0;
     foreach(object item in WidgetClient.Items(WidgetClient.Get(data,"agents"))){
      var agent=WidgetClient.Obj(item);
      if(agent==null||!String.Equals(WidgetClient.Str(agent,"id"),taskId,StringComparison.Ordinal))continue;
      matches++;root=agent;
     }
