 static string DiagnosticsText(Dictionary<string,object> d){if(d==null)return "";var parts=new List<string>();if(TimestampValid(WidgetClient.Get(d,"startedAt")))parts.Add("开始 "+LocalClock(WidgetClient.Str(d,"startedAt")));if(TimestampValid(WidgetClient.Get(d,"finishedAt")))parts.Add("结束 "+LocalClock(WidgetClient.Str(d,"finishedAt")));string phase=WidgetClient.Str(d,"lastPhase");if(Array.IndexOf(new[]{"queued","starting","waiting","generating","stopping"},phase)>=0)parts.Add("阶段 "+PhaseText(phase));string reason=WidgetClient.Str(d,"terminationReason");if(Array.IndexOf(new[]{"completed","budget_exhausted","cancelled","process_error","invalid_output"},reason)>=0)parts.Add("结束原因 "+ReasonText(reason));double ms;if(ComparisonNumber(WidgetClient.Get(d,"timeoutMs"),out ms)&&ms>=0)parts.Add("总预算 "+Number(ms/1000)+" 秒");if(ComparisonNumber(WidgetClient.Get(d,"elapsedMs"),out ms)&&ms>=0)parts.Add("已耗时 "+Number(ms/1000)+" 秒");if(ComparisonNumber(WidgetClient.Get(d,"firstEventElapsedMs"),out ms)&&ms>=0)parts.Add("首个事件 "+Number(ms/1000)+" 秒");if(ComparisonNumber(WidgetClient.Get(d,"lastEventElapsedMs"),out ms)&&ms>=0)parts.Add("最后事件 "+Number(ms/1000)+" 秒");string cleanup=WidgetClient.Str(d,"cleanupStatus");if(cleanup=="confirmed")parts.Add("清理已确认");else if(cleanup=="unconfirmed")parts.Add("清理未确认，临时文件可能保留");else if(cleanup=="not_needed")parts.Add("无需清理");if(WidgetClient.Str(d,"configWarning")=="timeout_config_invalid")parts.Add("超时配置无效，已使用默认时长");if(parts.Count==0)return "";return "运行诊断 · "+String.Join(" · ",parts.ToArray());}
